static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the timeBucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the new day by dividing the day by dayStep and multiplying back
        int newDay = (day / dayStep) * dayStep;

        // If the day is not a multiple of dayStep, adjust it to the nearest lower multiple
        if (day % dayStep != 0) {
            newDay -= dayStep;
        }

        // Ensure the new day is within the valid range for the month
        if (newDay < 1) {
            newDay = 1;
        }

        // Return the new time bucket
        return year * 10000 + month * 100 + newDay;
    } catch (Exception e) {
        // Handle any unexpected exceptions
        throw new IllegalArgumentException("Invalid timeBucket or dayStep provided", e);
    }
}

