        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int totalSize = 0;
    while (node != null) {
        out.write(node.buffer, 0, node.offset);
        totalSize += node.offset;
        node = node.next;
    }
    return totalSize;
}

