    if (inputStream.available() == 0) {
        return 0;
    }
    try {
        int tag = inputStream.read();
        if (tag == -1) {
            return 0;
        }
        return tag;
    } catch (IOException e) {
        throw new IOException("Error reading tag from input stream", e);
    }
}

